const job = new Promise((resolve, reject) => reject(new Error("timeout")));

job
  .then((result) => console.log("done " + result))
  .catch((error) => error.message.length)
  .finally(() => {
    console.log("cleanup");
    return 99;
  })
  .then((value) => console.log("value " + value));
